import csv

with open("data/_tmp/label_batches/batch_12.csv", encoding="utf-8") as f:
    in_rows = list(csv.DictReader(f))
in_keys = [r["key"] for r in in_rows]

with open("config/model_labels/batch_12.csv", encoding="utf-8", newline="") as f:
    out_rows = list(csv.DictReader(f))

print("header ok:", list(out_rows[0].keys()) == ["key","disciplines","tier","route","candidate","reason"] if out_rows else "n/a")
print("input rows:", len(in_rows), "output rows:", len(out_rows))

out_keys = [r["key"] for r in out_rows]
print("same count:", len(in_keys) == len(out_keys))
print("same key set:", set(in_keys) == set(out_keys))
print("same order:", in_keys == out_keys)
print("dup output keys:", len(out_keys) != len(set(out_keys)))

DISC = {"Speed and sprint","Strength and power","Conditioning and energy systems","Rehab and return to play",
 "Injury risk and prevention","Load monitoring and GPS","Testing and assessment","Recovery and sleep",
 "Nutrition and body composition","Coaching, skill acquisition and constraints-led approach",
 "Periodization and programming","Anatomy, physiology and biomechanics","Data, technology and reporting",
 "Leadership, culture and psychology","Female athlete","Youth and development"}
ROUTES = {"paper to Zotero","already in Zotero","book","atomize","transcribe","catalog only","skip"}

problems = []
tierB = tierC = yes_n = 0
zmap = {}
for r in in_rows:
    zmap[r["key"]] = r.get("zotero_status","")

for r in out_rows:
    k = r["key"]; disc=r["disciplines"]; tier=r["tier"]; route=r["route"]; cand=r["candidate"]; reason=r["reason"]
    if tier not in ("B","C"): problems.append(("tier",k,tier))
    if route not in ROUTES: problems.append(("route",k,route))
    if cand not in ("yes","no"): problems.append(("cand",k,cand))
    dlist = [d for d in disc.split(";") if d]
    if any(d not in DISC for d in dlist): problems.append(("discstr",k,disc))
    if tier == "C":
        tierC += 1
        if disc != "" or route != "skip": problems.append(("Cshape",k,disc,route))
    if tier == "B":
        tierB += 1
        if not (1 <= len(dlist) <= 3): problems.append(("Bdisccount",k,disc))
    if cand == "yes": yes_n += 1
    if len(reason.split()) >= 15: problems.append(("reasonlen",k,reason))
    zs = zmap.get(k,"")
    if zs in ("verified","skipped_existing_pdf"):
        if not (tier=="B" and route=="already in Zotero"):
            problems.append(("zotero-rule",k,zs,tier,route))

print("tierB", tierB, "tierC", tierC, "yes", yes_n, "pct_yes", round(100*yes_n/len(out_rows),1))
print("problems:", len(problems))
for p in problems[:40]:
    print(p)

